import { defineTool as defineTool6 } from "npm:@lovable.dev/mcp-js@2.0.2";
import { z as z6 } from "npm:zod@^3.25.76";
var list_datasets_default = defineTool6({
  name: "list_datasets",
  title: "List datasets",
  description: "\u0627\u0633\u062A\u0639\u0631\u0627\u0636 \u0645\u0635\u0627\u062F\u0631 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0645\u062A\u0627\u062D\u0629 \u0644\u0644\u0642\u0631\u0627\u0621\u0629 (\u062C\u062F\u0627\u0648\u0644 \u0648\u0639\u0631\u0648\u0636) \u0645\u0639 \u0627\u0644\u0642\u0633\u0645 \u0648\u0627\u0644\u0623\u0639\u0645\u062F\u0629 \u0648\u0627\u0644\u0639\u0644\u0627\u0642\u0627\u062A. \u0627\u0633\u062A\u062E\u062F\u0645\u0647\u0627 \u0644\u0645\u0639\u0631\u0641\u0629 \u0623\u0633\u0645\u0627\u0621 \u0627\u0644\u0623\u0639\u0645\u062F\u0629 \u0642\u0628\u0644 \u0627\u0633\u062A\u062F\u0639\u0627\u0621 query_dataset.",
  inputSchema: {
    section: z6.string().optional().describe("\u062A\u0635\u0641\u064A\u0629 \u0628\u0627\u0644\u0642\u0633\u0645\u060C \u0645\u062B\u0644 inventory \u0623\u0648 finance."),
    search: z6.string().optional().describe("\u0628\u062D\u062B \u0646\u0635\u064A \u0641\u064A \u0627\u0633\u0645 \u0627\u0644\u0645\u0635\u062F\u0631 \u0623\u0648 \u0623\u0639\u0645\u062F\u062A\u0647."),
    include_columns: z6.boolean().optional().describe("\u062A\u0636\u0645\u064A\u0646 \u0623\u0633\u0645\u0627\u0621 \u0627\u0644\u0623\u0639\u0645\u062F\u0629 (\u0627\u0641\u062A\u0631\u0627\u0636\u064A true)."),
    limit: z6.number().optional().describe("\u0639\u062F\u062F \u0627\u0644\u0646\u062A\u0627\u0626\u062C (\u0627\u0641\u062A\u0631\u0627\u0636\u064A 100\u060C \u0623\u0642\u0635\u0649 400)."),
    offset: z6.number().optional().describe("\u0628\u062F\u0627\u064A\u0629 \u0627\u0644\u062A\u0631\u0642\u064A\u0645 (\u0627\u0641\u062A\u0631\u0627\u0636\u064A 0).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ section, search, include_columns, limit, offset }) => {
    const s = (search ?? "").trim().toLowerCase();
    const all = DATASETS.filter(
      (d) => (!section || d.section === section) && (!s || d.name.toLowerCase().includes(s) || d.columns.some((c) => c.toLowerCase().includes(s)))
    );
    const take = Math.min(Math.max(limit ?? 100, 1), 400);
    const skip = Math.max(offset ?? 0, 0);
    const page = all.slice(skip, skip + take).map((d) => ({
      name: d.name,
      section: d.section,
      section_label_ar: SECTION_LABELS[d.section] ?? d.section,
      kind: d.name.startsWith("v_") ? "view" : "table",
      ...include_columns === false ? {} : { columns: d.columns },
      references: FOREIGN_KEYS.filter((f) => f.table === d.name).map((f) => `${f.column} -> ${f.references}`)
    }));
    const payload = { total: all.length, returned: page.length, offset: skip, limit: take, datasets: page };
    return { content: [{ type: "text", text: JSON.stringify(payload) }], structuredContent: payload };
  }
});

